+func TestNormalizeAgentString(t *testing.T) {
+	t.Parallel()
+	tests := []struct {
+		input string
+		want  string
+	}{
+		{"Claude Code", "claude"},
+		{"claude-code", "claude"},
+		{"claude", "claude"},
+		{"Gemini CLI", "gemini"},
+		{"gemini", "gemini"},
+		{"copilot-cli", "copilot"},
+		{"Copilot CLI", "copilot"},
+		{"OpenCode", "opencode"},
+		{"open-code", "opencode"},
+		{"factoryai-droid", "droid"},
+		{"Factory AI Droid", "droid"},
+		{"FactoryAIDroid", "droid"},
+		{"codex", "codex"},
+		{"pi", "pi"},
+		{"cursor", "cursor"},
+		{"kiro", "kiro"},
+		{"amp", "amp"},
+		{"some-unknown-agent", "unknown"},
+		{"", "unknown"},
+	}
+	for _, tt := range tests {
+		t.Run(tt.input, func(t *testing.T) {
+			t.Parallel()
+			got := normalizeAgentString(tt.input)
+			if got != tt.want {
+				t.Errorf("normalizeAgentString(%q) = %q, want %q", tt.input, got, tt.want)
+			}
+		})
+	}
+}
